import React, { useState, useEffect } from 'react';
import Navbar from '../components/Navbar';
import { 
  FaPlus, FaTrash, FaCalendarAlt, FaClock, FaBrain, FaLightbulb, 
  FaChartLine, FaCheckCircle, FaCircle, FaBook, FaClipboardList,
  FaBriefcase, FaUsers, FaGraduationCap, FaFire, FaSmile, FaMeh, FaFrown
} from 'react-icons/fa';

function AcademicLoad() {
  const [items, setItems] = useState([]);
  const [showAddForm, setShowAddForm] = useState(false);
  const [aiInsight, setAiInsight] = useState('');
  const [completionRate, setCompletionRate] = useState(0);
  const [stressLevel, setStressLevel] = useState('medium');
  const [newItem, setNewItem] = useState({
    title: '',
    type: 'exam',
    dueDate: '',
    dueTime: '',
    priority: 'medium',
    completed: false
  });

  useEffect(() => {
    const saved = localStorage.getItem('academicLoad');
    if (saved) {
      const loadedItems = JSON.parse(saved);
      setItems(loadedItems);
      calculateStats(loadedItems);
      generateAIInsight(loadedItems);
    }
  }, []);

  const calculateStats = (taskList) => {
    const completed = taskList.filter(i => i.completed).length;
    const rate = taskList.length > 0 ? Math.round((completed / taskList.length) * 100) : 0;
    setCompletionRate(rate);
    
    const pendingHigh = taskList.filter(i => !i.completed && i.priority === 'high').length;
    if (pendingHigh >= 3) setStressLevel('high');
    else if (pendingHigh >= 1) setStressLevel('medium');
    else setStressLevel('low');
  };

  const generateAIInsight = (taskList) => {
    const pending = taskList.filter(i => !i.completed);
    const highPriority = pending.filter(i => i.priority === 'high');
    const dueSoon = pending.filter(i => {
      const dueDate = new Date(i.dueDate);
      const today = new Date();
      const diffTime = dueDate - today;
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      return diffDays <= 3 && diffDays >= 0;
    });
    
    let insight = '';
    if (pending.length === 0) {
      insight = '🎉 Amazing! All tasks completed. Take a well-deserved break!';
    } else if (highPriority.length >= 2) {
      insight = `🧠 AI Insight: You have ${highPriority.length} high-priority tasks. Consider a 25-min focus session now.`;
    } else if (dueSoon.length > 0) {
      insight = `📅 AI Insight: ${dueSoon.length} task${dueSoon.length > 1 ? 's are' : ' is'} due soon. Stay on track!`;
    } else if (pending.length >= 5) {
      insight = `📚 AI Insight: Heavy workload detected. Take short breaks between tasks to avoid burnout.`;
    } else {
      insight = `💡 AI Insight: You're making progress! Keep up the momentum.`;
    }
    setAiInsight(insight);
  };

  const saveToLocal = (newItems) => {
    setItems(newItems);
    localStorage.setItem('academicLoad', JSON.stringify(newItems));
    calculateStats(newItems);
    generateAIInsight(newItems);
  };

  const addItem = () => {
    if (newItem.title && newItem.dueDate) {
      const newItems = [...items, { ...newItem, id: Date.now() }];
      saveToLocal(newItems);
      setNewItem({ title: '', type: 'exam', dueDate: '', dueTime: '', priority: 'medium', completed: false });
      setShowAddForm(false);
    }
  };

  const toggleComplete = (id) => {
    const newItems = items.map(item => item.id === id ? { ...item, completed: !item.completed } : item);
    saveToLocal(newItems);
  };

  const deleteItem = (id) => {
    const newItems = items.filter(item => item.id !== id);
    saveToLocal(newItems);
  };

  const getTypeIcon = (type) => {
    switch(type) {
      case 'exam': return <FaBook color="#e74c3c" size={14} />;
      case 'assignment': return <FaClipboardList color="#f39c12" size={14} />;
      case 'club': return <FaUsers color="#2ecc71" size={14} />;
      case 'work': return <FaBriefcase color="#3498db" size={14} />;
      default: return <FaGraduationCap color="#9b59b6" size={14} />;
    }
  };

  const getTypeLabel = (type) => {
    switch(type) {
      case 'exam': return 'Exam';
      case 'assignment': return 'Assignment';
      case 'club': return 'Club';
      case 'work': return 'Work';
      default: return 'Task';
    }
  };

  const getPriorityColor = (priority) => {
    if (priority === 'high') return '#e74c3c';
    if (priority === 'medium') return '#f39c12';
    return '#2ecc71';
  };

  const getPriorityBg = (priority) => {
    if (priority === 'high') return '#e74c3c10';
    if (priority === 'medium') return '#f39c1210';
    return '#2ecc7110';
  };

  const upcomingItems = items.filter(i => !i.completed).sort((a,b) => new Date(a.dueDate) - new Date(b.dueDate));
  const completedItems = items.filter(i => i.completed);
  
  const getStressIcon = () => {
    if (stressLevel === 'high') return <FaFrown size={20} color="#e74c3c" />;
    if (stressLevel === 'medium') return <FaMeh size={20} color="#f39c12" />;
    return <FaSmile size={20} color="#2ecc71" />;
  };

  const getStressText = () => {
    if (stressLevel === 'high') return 'High Stress';
    if (stressLevel === 'medium') return 'Moderate Stress';
    return 'Low Stress';
  };

  const types = [
    { value: 'exam', label: '📚 Exam', icon: <FaBook size={12} />, color: '#e74c3c' },
    { value: 'assignment', label: '📝 Assignment', icon: <FaClipboardList size={12} />, color: '#f39c12' },
    { value: 'club', label: '🎯 Club Event', icon: <FaUsers size={12} />, color: '#2ecc71' },
    { value: 'work', label: '💼 Work Shift', icon: <FaBriefcase size={12} />, color: '#3498db' },
  ];

  return (
    <div style={styles.container}>
      <Navbar />
      <div style={styles.navSpacer} />
      
      <div style={styles.content}>
        <div style={styles.header}>
          <h1 style={styles.title}>📚 Academic & Life Load</h1>
          <p style={styles.subtitle}>Track exams, assignments, clubs, and work shifts</p>
        </div>

        {/* AI Insight Card */}
        <div style={styles.aiCard}>
          <div style={styles.aiIcon}><FaBrain size={18} color="#667eea" /></div>
          <div style={styles.aiContent}>
            <span style={styles.aiLabel}>🧠 AI Insight</span>
            <p style={styles.aiText}>{aiInsight || "Loading insights..."}</p>
          </div>
        </div>

        {/* Stats Cards */}
        <div style={styles.statsGrid}>
          <div style={{...styles.statCard, borderTop: '3px solid #e74c3c'}}>
            <div style={styles.statIcon}><FaFire color="#e74c3c" size={22} /></div>
            <div style={styles.statNumber}>{items.filter(i => !i.completed).length}</div>
            <div style={styles.statLabel}>Pending Tasks</div>
          </div>
          <div style={{...styles.statCard, borderTop: '3px solid #2ecc71'}}>
            <div style={styles.statIcon}><FaCheckCircle color="#2ecc71" size={22} /></div>
            <div style={styles.statNumber}>{completedItems.length}</div>
            <div style={styles.statLabel}>Completed</div>
          </div>
          <div style={{...styles.statCard, borderTop: '3px solid #3498db'}}>
            <div style={styles.statIcon}><FaChartLine color="#3498db" size={22} /></div>
            <div style={styles.statNumber}>{items.length}</div>
            <div style={styles.statLabel}>Total Tasks</div>
          </div>
          <div style={{...styles.statCard, borderTop: `3px solid ${stressLevel === 'high' ? '#e74c3c' : stressLevel === 'medium' ? '#f39c12' : '#2ecc71'}`}}>
            <div style={styles.statIcon}>{getStressIcon()}</div>
            <div style={styles.statNumber}>{getStressText()}</div>
            <div style={styles.statLabel}>Stress Meter</div>
          </div>
        </div>

        {/* Progress Section */}
        <div style={styles.progressSection}>
          <div style={styles.progressRing}>
            <svg width="80" height="80" viewBox="0 0 120 120">
              <circle cx="60" cy="60" r="50" fill="none" stroke="#e0e0e0" strokeWidth="8"/>
              <circle 
                cx="60" cy="60" r="50" fill="none" 
                stroke="url(#grad)" strokeWidth="8" 
                strokeDasharray={2 * Math.PI * 50}
                strokeDashoffset={2 * Math.PI * 50 * (1 - completionRate / 100)}
                strokeLinecap="round"
                transform="rotate(-90 60 60)"
              />
              <defs>
                <linearGradient id="grad" x1="0%" y1="0%" x2="100%" y2="100%">
                  <stop offset="0%" stopColor="#667eea"/>
                  <stop offset="100%" stopColor="#764ba2"/>
                </linearGradient>
              </defs>
              <text x="60" y="65" textAnchor="middle" fontSize="18" fontWeight="bold" fill="#333">{completionRate}%</text>
            </svg>
            <p style={styles.progressLabel}>Completion</p>
          </div>
          <div style={styles.progressBarCard}>
            <div style={styles.progressBarHeader}>
              <span>📊 Workload Progress</span>
              <span>{completionRate}%</span>
            </div>
            <div style={styles.progressBarBg}>
              <div style={{...styles.progressBarFill, width: `${completionRate}%`}} />
            </div>
            <p style={styles.progressHint}>{items.length - completedItems.length} tasks remaining</p>
          </div>
        </div>

        {/* Add Task Button */}
        <button onClick={() => setShowAddForm(true)} style={styles.addMainBtn}>
          <FaPlus size={14} /> Add New Task
        </button>

        {/* Upcoming Tasks */}
        <div style={styles.section}>
          <h2 style={styles.sectionTitle}>⏰ Upcoming Tasks</h2>
          {upcomingItems.length === 0 && <p style={styles.empty}>✨ All caught up! Great job! ✨</p>}
          {upcomingItems.map(item => (
            <div key={item.id} style={{...styles.taskCard, background: getPriorityBg(item.priority), borderLeft: `4px solid ${getPriorityColor(item.priority)}`}}>
              <div style={styles.taskLeft}>
                <div onClick={() => toggleComplete(item.id)} style={styles.checkbox}>
                  {item.completed ? <FaCheckCircle color="#2ecc71" size={20} /> : <FaCircle color="#ccc" size={20} />}
                </div>
                <div style={styles.taskIcon}>{getTypeIcon(item.type)}</div>
                <div style={styles.taskDetails}>
                  <h4 style={{textDecoration: item.completed ? 'line-through' : 'none'}}>
                    {getTypeLabel(item.type)}: {item.title}
                  </h4>
                  <p><FaCalendarAlt size={10} /> {new Date(item.dueDate).toLocaleDateString()} {item.dueTime && <><FaClock size={10} /> {item.dueTime}</>}</p>
                </div>
              </div>
              <button onClick={() => deleteItem(item.id)} style={styles.deleteBtn}><FaTrash size={14} /></button>
            </div>
          ))}
        </div>

        {/* Completed Tasks */}
        {completedItems.length > 0 && (
          <div style={styles.section}>
            <h2 style={styles.sectionTitle}>✅ Completed Tasks</h2>
            {completedItems.map(item => (
              <div key={item.id} style={{...styles.taskCard, opacity: 0.7, background: '#f0fff0'}}>
                <div style={styles.taskLeft}>
                  <div onClick={() => toggleComplete(item.id)} style={styles.checkbox}>
                    <FaCheckCircle color="#2ecc71" size={20} />
                  </div>
                  <div style={styles.taskIcon}>{getTypeIcon(item.type)}</div>
                  <div style={styles.taskDetails}>
                    <h4 style={{textDecoration: 'line-through'}}>{getTypeLabel(item.type)}: {item.title}</h4>
                    <p>✅ Completed</p>
                  </div>
                </div>
                <button onClick={() => deleteItem(item.id)} style={styles.deleteBtn}><FaTrash size={14} /></button>
              </div>
            ))}
          </div>
        )}

        {/* Modal */}
        {showAddForm && (
          <div style={styles.modal} onClick={() => setShowAddForm(false)}>
            <div style={styles.modalContent} onClick={(e) => e.stopPropagation()}>
              <h3 style={styles.modalTitle}>➕ Add New Task</h3>
              <input type="text" placeholder="Task title" value={newItem.title} onChange={(e) => setNewItem({...newItem, title: e.target.value})} style={styles.modalInput} />
              
              <div style={styles.typeGrid}>
                {types.map(t => (
                  <button key={t.value} onClick={() => setNewItem({...newItem, type: t.value})} style={{...styles.typeBtn, background: newItem.type === t.value ? `${t.color}20` : '#f5f5f5', border: newItem.type === t.value ? `1px solid ${t.color}` : '1px solid #e0e0e0'}}>
                    {t.icon} {t.label}
                  </button>
                ))}
              </div>
              
              <input type="date" value={newItem.dueDate} onChange={(e) => setNewItem({...newItem, dueDate: e.target.value})} style={styles.modalInput} />
              <input type="time" value={newItem.dueTime} onChange={(e) => setNewItem({...newItem, dueTime: e.target.value})} style={styles.modalInput} />
              
              <div style={styles.priorityRow}>
                <button onClick={() => setNewItem({...newItem, priority: 'low'})} style={{...styles.priorityBtn, background: newItem.priority === 'low' ? '#2ecc71' : '#f0f0f0', color: newItem.priority === 'low' ? 'white' : '#555'}}>🟢 Low</button>
                <button onClick={() => setNewItem({...newItem, priority: 'medium'})} style={{...styles.priorityBtn, background: newItem.priority === 'medium' ? '#f39c12' : '#f0f0f0', color: newItem.priority === 'medium' ? 'white' : '#555'}}>🟡 Medium</button>
                <button onClick={() => setNewItem({...newItem, priority: 'high'})} style={{...styles.priorityBtn, background: newItem.priority === 'high' ? '#e74c3c' : '#f0f0f0', color: newItem.priority === 'high' ? 'white' : '#555'}}>🔴 High</button>
              </div>
              
              <div style={styles.modalActions}>
                <button onClick={addItem} style={styles.saveBtn}>Save Task</button>
                <button onClick={() => setShowAddForm(false)} style={styles.cancelBtn}>Cancel</button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

